# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_avgpool_linear_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias);

torch::Tensor fused_avgpool_linear(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "x must be 4D [B,C,H,W]");
    TORCH_CHECK(weight.dim() == 2, "weight must be 2D [O,C]");
    TORCH_CHECK(x.size(1) == weight.size(1),
                "channel dim mismatch: x.size(1)=", x.size(1),
                " weight.size(1)=", weight.size(1));
    if (bias.numel() > 0) {
        TORCH_CHECK(bias.dim() == 1, "bias must be 1D");
        TORCH_CHECK(bias.size(0) == weight.size(0),
                    "bias size mismatch");
    }
    return fused_avgpool_linear_cuda(x.contiguous(), weight.contiguous(),
                                     bias.contiguous());
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_avgpool_linear", &fused_avgpool_linear,
          "Fused global average pool + linear (CUDA)");
