"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Each thread computes one output element (b, o).
// It accumulates sum over c of (sum_{h,w} x[b,c,h,w] / (H*W)) * weight[o,c]
// then adds bias[o].
template <typename scalar_t>
__global__ void fused_avgpool_linear_kernel(
    const scalar_t* __restrict__ x,       // [B, C, H, W]
    const scalar_t* __restrict__ weight,  // [O, C]
    const scalar_t* __restrict__ bias,    // [O] or nullptr
    scalar_t* __restrict__ out,           // [B, O]
    int B, int C, int H, int W, int O,
    bool has_bias) {

    int b = blockIdx.x;
    int o = blockIdx.y * blockDim.x + threadIdx.x;
    if (b >= B || o >= O) return;

    int HW = H * W;
    float inv_hw = 1.0f / static_cast<float>(HW);
    float acc = 0.0f;

    for (int c = 0; c < C; ++c) {
        float channel_sum = 0.0f;
        const scalar_t* x_ptr = x + b * (C * HW) + c * HW;
        // Unroll inner loop for better ILP
        int hw = 0;
        for (; hw + 3 < HW; hw += 4) {
            channel_sum += static_cast<float>(x_ptr[hw])
                         + static_cast<float>(x_ptr[hw+1])
                         + static_cast<float>(x_ptr[hw+2])
                         + static_cast<float>(x_ptr[hw+3]);
        }
        for (; hw < HW; ++hw) {
            channel_sum += static_cast<float>(x_ptr[hw]);
        }
        float mean_c = channel_sum * inv_hw;
        acc += mean_c * static_cast<float>(weight[o * C + c]);
    }

    if (has_bias) {
        acc += static_cast<float>(bias[o]);
    }
    out[b * O + o] = static_cast<scalar_t>(acc);
}

torch::Tensor fused_avgpool_linear_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias) {

    int B = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    int O = weight.size(0);
    bool has_bias = bias.numel() > 0;

    auto out = torch::empty({B, O}, weight.options());

    const int threads = 128;
    dim3 grid(B, (O + threads - 1) / threads);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(x.scalar_type(), "fused_avgpool_linear_cuda", [&] {
        fused_avgpool_linear_kernel<scalar_t><<<grid, threads>>>(
            x.data_ptr<scalar_t>(),
            weight.data_ptr<scalar_t>(),
            has_bias ? bias.data_ptr<scalar_t>() : nullptr,
            out.data_ptr<scalar_t>(),
            B, C, H, W, O, has_bias
        );
    });

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    def __init__(self, input_channels, stages, block_widths, output_classes):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        """
                :param input_channels: int, Number of input channels for the first layer
                :param stages: int, Number of stages in the RegNet architecture
                :param block_widths: List[int], Width (number of channels) for each block in the stages
                :param output_classes: int, Number of output classes for classification
                """
        self.stages = stages
        self.block_widths = block_widths
        layers = []
        current_channels = input_channels
        for i in range(stages):
                    layers.append(self._make_stage(current_channels, block_widths[i]))
                    current_channels = block_widths[i]
        self.feature_extractor = nn.Sequential(*layers)
        self.fc = nn.Linear(block_widths[-1], output_classes)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Baseline fallback keeps the official PyTorch forward path.
        # After implementing CUDA_CPP_SRC / CUDA_CU_SRC, call _stark_get_extension().your_entrypoint(...).
        """
                Forward pass through the RegNet model.
                :param x: torch.Tensor of shape (batch_size, input_channels, height, width)
                :return: torch.Tensor of shape (batch_size, output_classes)
                """
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.feature_extractor(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if x.is_cuda and x.dim() == 4 and self.fc.weight.is_cuda:
            _bias = self.fc.bias.contiguous() if self.fc.bias is not None else torch.empty(0, device=x.device, dtype=self.fc.weight.dtype)
            x = _stark_get_extension().fused_avgpool_linear(
                x.contiguous(), self.fc.weight.contiguous(), _bias)
        else:
            x = torch.mean(x, dim=[2, 3])
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        if x.dim() == 2 and x.size(1) == self.fc.in_features:
            x = self.fc(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        return x
